export function setupConnect(e={}){const t=new URL(window.location.href);if(!t.pathname.startsWith("/webcontainer/connect/"))throw new Error(`This function must be used on a '/webcontainer/connect' endpoint. Used in ${t.pathname}`);if(!window.opener)throw new Error("This page must have an opener. You must serve it with appropriate headers");const n=new URL(e.editorOrigin??"https://stackblitz.com");n.pathname=t.pathname;const o=document.createElement("iframe");o.style.display="none",window.addEventListener("message",e=>{if("close"===e.data)return void window.close();const t=findMessagePorts(e.data);e.source===window.opener?o.contentWindow.postMessage(e.data,"*",t):window.opener.postMessage(e.data,"*",t)}),o.src=n.toString(),document.body.appendChild(o)}const e=[];function findMessagePorts(t){if(!t||"object"!=typeof t)return e;const n=[];for(const e in t){const o=t[e];"[object MessagePort]"!==Object.prototype.toString.call(o)?n.push(...findMessagePorts(o)):n.push(o)}return n}